/**
 * Parse and sign with OpenSSH / PEM private keys generated by ssh-keygen.
 */
import { execSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

const dir = mkdtempSync(join(tmpdir(), "ternssh-keys-"));

function run(cmd) {
  execSync(cmd, { stdio: "pipe" });
}

function sshKeygen(args, file) {
  run(`ssh-keygen -q ${args} -N "" -f "${file}" -C test`);
}

function decodeSshString(blob, offset) {
  const len =
    ((blob[offset] << 24) | (blob[offset + 1] << 16) | (blob[offset + 2] << 8) | blob[offset + 3]) >>> 0;
  const start = offset + 4;
  return { value: blob.subarray(start, start + len), next: start + len };
}

async function main() {
  const { parsePrivateKey } = await import(
    pathToFileURL(join(import.meta.dirname, "../src/ssh/openssh-key.ts")).href
  );

  const cases = [
    { name: "openssh-ed25519", args: "-t ed25519" },
    { name: "openssh-rsa", args: "-t rsa -b 2048" },
    { name: "openssh-ecdsa256", args: "-t ecdsa -b 256" },
    { name: "openssh-ecdsa384", args: "-t ecdsa -b 384" },
    { name: "openssh-ecdsa521", args: "-t ecdsa -b 521" },
    { name: "pem-rsa", args: "-t rsa -b 2048 -m PEM" },
    { name: "pkcs8-rsa", args: "-t rsa -b 2048 -m PKCS8" },
  ];

  const data = new TextEncoder().encode("ternssh-openssh-key-test");

  for (const item of cases) {
    const file = join(dir, item.name);
    sshKeygen(item.args, file);
    const pem = readFileSync(file, "utf8");
    if (item.name.startsWith("openssh-") && !pem.includes("BEGIN OPENSSH PRIVATE KEY")) {
      throw new Error(`${item.name} is not OpenSSH format`);
    }
    const key = await parsePrivateKey(pem);
    const signatureBlob = await key.sign(data);
    const alg = decodeSshString(signatureBlob, 0);
    const sig = decodeSshString(signatureBlob, alg.next);
    const algName = new TextDecoder().decode(alg.value);
    if (algName !== key.algorithm) {
      throw new Error(`${item.name}: algorithm mismatch ${algName} vs ${key.algorithm}`);
    }
    if (sig.value.length < 32) {
      throw new Error(`${item.name}: signature too short`);
    }
    if (key.publicKeyBlob.length < 20) {
      throw new Error(`${item.name}: public blob too short`);
    }
    console.log(`ok  ${item.name.padEnd(18)} ${key.algorithm}`);
  }

  const encFile = join(dir, "openssh-ed25519-enc");
  run(`ssh-keygen -q -t ed25519 -N "secret123" -f "${encFile}" -C enc`);
  const encPem = readFileSync(encFile, "utf8");
  const encKey = await parsePrivateKey(encPem, "secret123");
  await encKey.sign(data);
  console.log(`ok  ${"openssh-ed25519-enc".padEnd(18)} ${encKey.algorithm} (encrypted)`);

  const rsaEncFile = join(dir, "openssh-rsa-enc");
  run(`ssh-keygen -q -t rsa -b 2048 -N "secret123" -f "${rsaEncFile}" -C enc`);
  const rsaEncKey = await parsePrivateKey(readFileSync(rsaEncFile, "utf8"), "secret123");
  await rsaEncKey.sign(data);
  console.log(`ok  ${"openssh-rsa-enc".padEnd(18)} ${rsaEncKey.algorithm} (encrypted)`);

  const crlfPem = readFileSync(join(dir, "openssh-rsa"), "utf8").replace(/\n/g, "\r\n");
  const crlfKey = await parsePrivateKey(crlfPem);
  await crlfKey.sign(data);
  console.log(`ok  ${"openssh-rsa-crlf".padEnd(18)} ${crlfKey.algorithm}`);

  let failed = false;
  try {
    await parsePrivateKey(encPem, "wrong-pass");
    failed = true;
  } catch (error) {
    if (!(error instanceof Error) || !error.message.includes("私钥密码错误")) {
      throw error;
    }
  }
  if (failed) throw new Error("encrypted key accepted a wrong passphrase");
  console.log("ok  encrypted key rejects wrong passphrase");
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(() => {
    rmSync(dir, { recursive: true, force: true });
  });
